WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_limits) AS tier_value FROM price_tiers) SELECT *, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value) AS tier_value_dense_rank, RANK() OVER (PARTITION BY plan, currency ORDER BY tier_value NULLS FIRST) AS tier_value_rank, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY tier_value) AS tier_value_percent_rank, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC) AS tier_value_dense_rank_2, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC NULLS FIRST) AS tier_value_dense_rank_3 FROM lines;
